<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/common.php';require dirname(__DIR__,2).'/noa-bridge/storage.php';require __DIR__.'/core.php';
if(empty($is_member)||($is_admin??'')!=='super'){http_response_code(403);exit('관리자 로그인이 필요합니다.');}
header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');
if(empty($_SESSION['noa_jukebox_csrf']))$_SESSION['noa_jukebox_csrf']=bin2hex(random_bytes(32));
$db=noa_bridge_pdo();$message='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 $token=$_POST['csrf']??'';if(!is_string($token)||!hash_equals($_SESSION['noa_jukebox_csrf'],$token)){http_response_code(403);exit;}
 $action=$_POST['action']??'';
 if(in_array($action,['sync','covers','inspect_audio','optimize','retry','audit'],true)){
  try{nj_schema($db);$db->prepare('INSERT INTO noa_jukebox_jobs(action,requested_by) VALUES(?,?)')->execute([$action,(string)$member['mb_id']]);$message='작업을 등록했습니다. 배치 실행기가 처리하면 결과가 갱신됩니다.';}
  catch(Throwable $e){$message='작업을 등록하지 못했습니다.';}
 }
}
$assets=nj_assets($db);$counts=['covers'=>0,'ready'=>0,'pending'=>0,'missing'=>0];foreach($assets as $r){$cover=nj_verified($r,'cover');$audio=nj_verified($r,'audio');$counts['covers']+=(int)$cover;$counts[$audio?'ready':'pending']++;if(($r['cover_path']&&!$cover)||($r['audio_path']&&!$audio))$counts['missing']++;}
function e($s):string{return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>JUKEBOX 관리 · NOA STUDIO</title><link rel="stylesheet" href="/noa-ui.css"><style>main{max-width:1100px;margin:auto;padding:24px}form{display:flex;gap:8px;flex-wrap:wrap}button{min-height:44px}table{width:100%;border-collapse:collapse}td,th{padding:12px;text-align:left;border-bottom:1px solid var(--border,#555)}.scroll{overflow:auto}pre{white-space:pre-wrap;word-break:break-word}small{display:block}summary{cursor:pointer}</style></head><body class="noa-page"><main><a href="/noa-music.php">← JUKEBOX</a><h1>JUKEBOX 관리</h1><p>카드 <?=count($assets)?>곡 등록 · 이미지 <?=$counts['covers']?>장 · 재생 가능 <?=$counts['ready']?>곡 · 음원 대기 <?=$counts['pending']?>곡 · 파일 누락·불일치 <?=$counts['missing']?>건</p><p role="status"><?=e($message)?></p><form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['noa_jukebox_csrf'])?>"><?php foreach(['sync'=>'전체 Suno URL 동기화','covers'=>'카드 이미지 수집','inspect_audio'=>'음원 확보 확인','optimize'=>'MP3 최적화','retry'=>'실패 항목 재처리','audit'=>'파일 누락 검사'] as $action=>$name):?><button name="action" value="<?=e($action)?>"><?=e($name)?></button><?php endforeach;?></form><p>접근이 제한된 음원은 대기 상태를 유지합니다. 분석·보정 결과는 실제 확보한 음원에만 표시됩니다.</p><div class="scroll"><table><thead><tr><th>곡</th><th>이미지</th><th>음원</th><th>분석·보정·오류</th></tr></thead><tbody><?php foreach($assets as $r):?><tr><td><?=e($r['title'])?><small><?=e($r['genre'].' / EP.'.$r['ep'])?></small></td><td><?=nj_verified($r,'cover')?'저장·검증 완료':'대기'?></td><td><?=nj_verified($r,'audio')?'재생 가능':'audio_pending'?></td><td><details><summary>결과 보기</summary><pre><?=e(json_encode(['source'=>json_decode($r['source_analysis']??'null',true),'correction'=>json_decode($r['correction']??'null',true),'final'=>json_decode($r['final_analysis']??'null',true),'errors'=>json_decode($r['errors']??'[]',true),'verified'=>$r['verified_at']],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT))?></pre></details></td></tr><?php endforeach;?></tbody></table></div><h2>배치 대기열</h2><?php try{foreach($db->query('SELECT id,action,status,created_at FROM noa_jukebox_jobs ORDER BY id DESC LIMIT 20') as $j)echo '<p>'.e(implode(' · ',array_values($j))).'</p>';}catch(Throwable $e){echo '<p>등록된 배치가 없습니다.</p>';}?></main></body></html>
